-- Archive question IDs and answers: old exam/practice foreign keys remain valid.
ALTER TABLE theory_questions ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1, ADD COLUMN applicable_categories VARCHAR(255) NULL, ADD COLUMN paralysis_categories VARCHAR(255) NULL, ADD COLUMN source_hash CHAR(64) NULL, ADD COLUMN source_page INT NULL, ADD INDEX idx_question_active_number (is_active,question_number);
ALTER TABLE theory_topics ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1;
UPDATE theory_questions SET is_active=0;
UPDATE theory_topics SET is_active=0;
UPDATE exam_configurations SET is_active=0;
