INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là trạng thái đứng yên của xe không giới hạn thời gian để cho người lên, xuống xe, xếp dỡ hàng hóa hoặc thực hiện công việc khác.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=14;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là trạng thái đứng yên tạm thời của xe trong một khoảng thời gian cần thiết đủ để cho người lên xe, xuống xe, xếp dỡ hàng hóa, kiểm tra kỹ thuật xe hoặc hoạt động khác. Khi dừng xe không được tắt máy và không được rời khỏi vị trí lái, trừ trường hợp rời khỏi vị trí lái để đóng, mở cửa xe, xếp dỡ hàng hóa, kiểm tra kỹ thuật xe nhưng phải sử dụng phanh đỗ xe hoặc thực hiện biện pháp an toàn khác.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=14;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là trạng thái đứng yên của xe không giới hạn thời gian giữa 02 lần vận chuyển hàng hóa hoặc hành khách.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=14;
