INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là thiết bị có đủ khả năng bảo đảm an toàn cho trẻ em ở tư thế ngồi hoặc nằm trên xe ô tô, được thiết kế để giảm nguy cơ chấn thương cho người dùng trong trường hợp xảy ra va chạm hoặc xe ô tô giảm tốc độ đột ngột, bằng cách hạn chế sự di chuyển của cơ thể trẻ em.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=17;
