INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),75,'Trường hợp người được chở trên xe mô tô, xe gắn máy, các loại xe tương tự xe mô tô và các loại xe tương tự xe gắn máy không đội "mũ bảo hiểm cho người đi mô tô, xe máy" hoặc không cài quai đúng quy cách (trừ trường hợp chở người bệnh đi cấp cứu, trẻ em dưới 06 tuổi, áp giải người có hành vi vi phạm pháp luật) thì việc xử phạt vi phạm hành chính được quy định như thế nào?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',19);
