INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Người được chở bị xử phạt, không xử phạt người điều khiển xe mô tô, xe gắn máy.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=75;
