INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),76,'Trong các trường hợp dưới đây, để bảo đảm an toàn khi tham gia giao thông, người lái xe mô tô cần thực hiện như thế nào?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',19);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải đội mũ bảo hiểm theo đúng quy chuẩn kỹ thuật quốc gia và cài quai đúng quy cách, không sử dụng ô, điện thoại di động, thiết bị âm thanh (trừ thiết bị trợ thính).',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=76;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải đội mũ bảo hiểm khi trời mưa gió hoặc trời quá nắng; có thể sử dụng ô, điện thoại di động, thiết bị âm thanh nhưng phải bảo đảm an toàn.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=76;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải đội mũ bảo hiểm khi cảm thấy mất an toàn giao thông hoặc khi chuẩn bị di chuyển quãng đường xa.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=76;
