INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),81,'Khi điều khiển xe chạy trên đường, biết có xe sau xin vượt, nếu đủ điều kiện an toàn người điều khiển phương tiện phải làm gì?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',20);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng tốc độ và ra hiệu cho xe sau vượt, không được gây trở ngại cho xe xin vượt.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=81;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giảm tốc độ, có tín hiệu rẽ phải để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết được vượt và đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua, không được cản trở đối với xe xin vượt.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=81;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cho xe đi sát về bên trái của phần đường xe chạy và ra hiệu cho xe sau vượt, không được gây trở ngại cho xe xin vượt.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=81;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),82,'Khi điều khiển xe chạy trên đường, biết có xe sau xin vượt, nếu không đủ điều kiện an toàn người điều khiển phương tiện phải làm gì?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',20);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có tín hiệu rẽ trái để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết là chưa được vượt.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=82;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tiếp tục đi cho đến khi đủ điều kiện an toàn, nếu xe sau vẫn xin vượt thì báo hiệu cho xe sau vượt.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=82;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng tốc độ để báo hiệu cho xe xin vượt biết là chưa được vượt.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=82;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),83,'Khi chuyển hướng, người lái xe, người điều khiển xe máy chuyên dùng phải làm gì để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',20);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải nhường đường cho người đi bộ, xe thô sơ, xe đi ngược chiều và chỉ chuyển hướng khi không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=83;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nhanh chóng chuyển hướng để không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=83;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Ra tín hiệu chuyển hướng để yêu cầu các phương tiện khác dừng lại cho xe chuyển hướng di chuyển.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=83;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),84,'Trước khi chuyển hướng, người điều khiển phương tiện tham gia giao thông đường bộ phải thực hiện như thế nào để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',21);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát gương, nếu không có phương tiện gần hướng rẽ thì nhanh chóng chuyển hướng.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=84;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát, bảo đảm khoảng cách an toàn với xe phía sau, giảm tốc độ và có tín hiệu báo hướng rẽ hoặc có tín hiệu bằng tay theo hướng rẽ đối với xe thô sơ không có đèn báo hướng rẽ, chuyển dần sang làn gần nhất với hướng rẽ. Tín hiệu báo hướng rẽ hoặc tín hiệu bằng tay phải sử dụng liên tục trong quá trình chuyển hướng. Khi bảo đảm an toàn, không gây trở ngại cho người và phương tiện khác mới được chuyển hướng.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=84;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát gương, tăng tốc độ, ra tín hiệu và chuyển hướng.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=84;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),85,'Khi lùi xe, người điều khiển phương tiện tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',NULL,NULL,1,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',21);
