INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),99,'Khi tới đường ngang không có người gác, chắn đường bộ, chuông, đèn tín hiệu, người tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',24);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng lại về bên phải đường của mình, trước vạch dừng xe và quan sát hai phía, khi không có phương tiện giao thông đường sắt tới mới được đi qua.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=99;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát hai phía, khi không có phương tiện giao thông đường sắt tới thì nhanh chóng đi qua.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=99;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng lại khoảng cách tối thiểu 3 mét tính từ ray đường sắt gần nhất, khi không có phương tiện giao thông đường sắt tới thì nhanh chóng đi qua.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=99;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),100,'Tại đường ngang, cầu chung đường sắt, khi có hiệu lệnh của nhân viên gác chắn, đèn đỏ sáng nhấp nháy, chuông kêu, chắn đường bộ đang dịch chuyển hoặc đã đóng, người tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',24);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng lại về bên trái đường của mình, trước vạch dừng xe.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=100;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng lại giữa đường của mình, trước vạch dừng xe.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=100;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng lại về bên phải đường của mình, trước vạch dừng xe.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=100;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),101,'Khi xe ô tô bị hư hỏng, bị tai nạn trên đường ngang, cầu chung đường sắt mà không thể di chuyển ngay khỏi phạm vi an toàn đường sắt, người lái xe và người có mặt xử lý như thế nào là đúng quy định?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',24);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Người lái xe và người có mặt phải ngay lập tức báo hiệu để dừng tàu, thực hiện các biện pháp bảo đảm an toàn.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=101;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Để xe lại, tìm cách báo cho người quản lý đường sắt, nhà ga nơi gần nhất.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=101;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Không di chuyển phương tiện, tự khắc phục sửa chữa.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=101;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),102,'Người tham gia giao thông đường bộ phải dừng lại về bên phải đường của mình trước vạch dừng xe tại đường ngang, cầu chung đường sắt khi có báo hiệu nào dưới đây?',NULL,NULL,1,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',24);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Hiệu lệnh của nhân viên gác chắn.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=102;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đèn đỏ sáng nhấp nháy, chuông kêu.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=102;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chắn đường bộ đang dịch chuyển hoặc đã đóng.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=102;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',1,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=102;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),103,'Người điều khiển phương tiện tham gia giao thông trong hầm đường bộ ngoài việc phải tuân thủ các quy tắc giao thông còn phải thực hiện những quy định nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',24);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe cơ giới, xe máy chuyên dùng phải bật đèn chiếu gần; xe thô sơ phải bật đèn hoặc có vật phát sáng báo hiệu; không dừng xe, đỗ xe trong hầm đường bộ; trường hợp gặp sự cố kỹ thuật hoặc bất khả kháng khác buộc phải dừng xe, đỗ xe, người lái xe, người điều khiển xe máy chuyên dùng phải đưa xe vào vị trí dừng xe, đỗ xe khẩn cấp, nếu không di chuyển được, phải có báo hiệu bằng đèn khẩn cấp và đặt biển hoặc đèn cảnh báo về phía sau xe khoảng cách bảo đảm an toàn.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=103;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe cơ giới, xe máy chuyên dùng phải bật đèn chiếu xa; được dừng xe, đỗ xe khi cần thiết.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=103;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải cho xe chạy trên một làn đường và chỉ chuyển làn ở nơi được phép; được quay đầu xe, lùi xe khi cần thiết.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=103;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),104,'Việc nối giữa xe kéo với xe được kéo trong trường hợp hệ thống hãm của xe được kéo không còn hiệu lực thì xe kéo nhau phải nối bằng cách nào?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',25);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nối bằng dây cáp có độ dài 6 mét.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=104;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nối bằng dây cáp có độ dài 8 mét.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=104;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nối bằng thanh nối cứng.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=104;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),105,'Xe kéo rơ moóc, xe ô tô đầu kéo khi tham gia giao thông đường bộ phải tuân thủ quy tắc giao thông nào ghi ở dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',25);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chỉ được kéo rơ moóc, sơ mi rơ moóc phù hợp với thiết kế của xe; việc kết nối xe kéo với rơ moóc, xe ô tô đầu kéo với sơ mi rơ moóc phải bảo đảm chắc chắn, an toàn.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=105;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải có tổng trọng lượng tương đương tổng trọng lượng của rơ moóc hoặc phải có hệ thống hãm có hiệu lực cho rơ moóc.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=105;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải được lắp phanh phụ theo quy định để đảm bảo an toàn.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=105;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),106,'Luật Trật tự, an toàn giao thông đường bộ quy định về xe kéo xe, xe kéo rơ moóc và xe ô tô đầu kéo kéo sơ mi rơ moóc như thế nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',25);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Một xe ô tô được kéo theo nhiều xe ô tô hoặc xe máy chuyên dùng khác khi xe được kéo không tự chạy được (trừ trường hợp xe vận chuyển hàng siêu trường, siêu trọng).',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=106;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe được kéo phải có người điều khiển và hệ thống lái của xe đó phải còn hiệu lực; việc nối xe kéo với xe được kéo phải bảo đảm chắc chắn, an toàn; trường hợp hệ thống hãm của xe được kéo không còn hiệu lực thì xe kéo nhau phải nối bằng thanh nối cứng. Phía trước của xe kéo và phía sau của xe được kéo phải có biển báo hiệu, có đèn cảnh báo nhấp nháy màu vàng.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=106;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=106;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),107,'Người điều khiển phương tiện tham gia giao thông đường bộ phải quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn trong các trường hợp nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',25);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có báo hiệu cảnh báo nguy hiểm hoặc có chướng ngại vật trên đường; chuyển hướng xe chạy hoặc tầm nhìn bị hạn chế.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=107;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nơi cầu, cống hẹp, đập tràn, đường ngầm, hầm chui, hầm đường bộ; có vật nuôi đi trên đường hoặc chăn thả ở ven đường.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=107;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Điểm dừng xe, đỗ xe trên đường bộ có khách đang lên, xuống xe.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=107;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',1,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=107;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),108,'Trên đường mà mỗi chiều đường xe chạy chỉ có một làn đường dành cho xe cơ giới, người lái xe không được vượt xe khác trong trường hợp nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',26);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có chướng ngại vật phía trước, xe chạy phía trước có tín hiệu vượt xe khác.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=108;
