INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),110,'Khi có xe xin vượt, người lái xe mô tô xử lý như thế nào nếu đủ điều kiện an toàn cho xe phía sau vượt?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',26);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giảm tốc độ, có tín hiệu rẽ phải để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết được vượt và đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua, không được cản trở đối với xe xin vượt.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=110;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Lái xe vào lề đường bên trái và giảm tốc độ để xe phía sau vượt qua, không được gây trở ngại đối với xe xin vượt.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=110;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng tốc độ, đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=110;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),111,'Những trường hợp nào dưới đây không được đi trên đường cao tốc, trừ người, phương tiện giao thông đường bộ và thiết bị phục vụ việc quản lý, bảo trì đường cao tốc?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',26);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe máy chuyên dùng có tốc độ thiết kế nhỏ hơn tốc độ tối thiểu quy định đối với đường cao tốc, xe chở người bốn bánh có gắn động cơ, xe chở hàng bốn bánh có gắn động cơ, xe mô tô, xe gắn máy, các loại xe tương tự xe mô tô, xe gắn máy, xe thô sơ, người đi bộ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=111;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe máy chuyên dùng có tốc độ thiết kế lớn hơn tốc độ tối thiểu quy định đối với đường cao tốc.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=111;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe ô tô và xe máy chuyên dùng có tốc độ thiết kế lớn hơn 80 km/h.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=111;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),112,'Khi tham gia giao thông trên đường cao tốc, xe ưu tiên đi làm nhiệm vụ khẩn cấp được đi ngược chiều trong trường hợp nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',27);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Được đi ngược chiều bất cứ làn đường nào của đường cao tốc có thể đi được.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=112;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chỉ được đi ngược chiều trên làn dừng xe khẩn cấp.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=112;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chỉ được đi ngược chiều trên làn đường sát dải phân cách của đường cao tốc.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=112;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),113,'Khi tham gia giao thông trên đường cao tốc, người lái xe không được thực hiện hành vi nào sau đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',27);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng, đỗ xe trên phần đường xe chạy, trừ trường hợp xe không thể di chuyển được vào làn đường khẩn cấp.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=113;
