INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),114,'Khi xe gặp sự cố kỹ thuật trên đường cao tốc, bạn phải xử lý như thế nào để bảo đảm an toàn giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',27);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Bật đèn tín hiệu khẩn cấp, dừng xe ngay lập tức và đặt biển báo hiệu nguy hiểm để cảnh báo cho các xe khác.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=114;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Bật tín hiệu khẩn cấp, lập tức đưa xe vào làn đường xe chạy bên phải trong cùng, đặt biển báo hiệu nguy hiểm để cảnh báo cho các xe khác.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=114;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng xe, đỗ xe ở làn dừng khẩn cấp cùng chiều xe chạy và phải có báo hiệu bằng đèn khẩn cấp; trường hợp xe không thể di chuyển được vào làn dừng khẩn cấp, phải có báo hiệu bằng đèn khẩn cấp và đặt biển hoặc đèn cảnh báo về phía sau xe khoảng cách tối thiểu 150 mét, nhanh chóng báo cho cơ quan Cảnh sát giao thông thực hiện nhiệm vụ bảo đảm trật tự, an toàn giao thông trên tuyến hoặc cơ quan quản lý đường cao tốc.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=114;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),115,'Trên đường cao tốc, người lái xe xử lý như thế nào khi đã vượt quá lối ra của đường định rẽ?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',27);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quay đầu xe, chạy trên lề đường có lối ra và rẽ khỏi đường cao tốc.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=115;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Lùi xe trên lề đường có lối ra và rẽ khỏi đường cao tốc.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=115;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tiếp tục lái xe và rẽ ở lối ra tiếp theo.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=115;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),116,'Khi xảy ra ùn tắc trên đường cao tốc có làn dừng xe khẩn cấp, người lái xe có được cho xe chạy ở làn dừng xe khẩn cấp để nhanh chóng thoát khỏi khu vực ùn tắc không (trừ xe ưu tiên)?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',27);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=116;
