INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nếu có làn đường tăng tốc thì phải cho xe chạy trên làn đường đó trước khi nhập vào làn đường của đường cao tốc.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=117;
