INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),119,'Theo quy định về độ tuổi, người đủ bao nhiêu tuổi trở lên thì được cấp giấy phép lái xe mô tô hai bánh có dung tích xi lanh đến 125 cm3 và xe ô tô chở người đến 8 chỗ (không kể chỗ của người lái xe); xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế đến 3.500 kg?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',28);
