INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chứng nhận đăng ký xe hoặc bản sao Chứng nhận đăng ký xe có chứng thực kèm bản gốc giấy tờ xác nhận của tổ chức tín dụng, chi nhánh ngân hàng nước ngoài còn hiệu lực trong trường hợp xe đang được thế chấp tại tổ chức tín dụng, chi nhánh ngân hàng nước ngoài.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=138;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giấy phép lái xe phù hợp với loại xe đang điều khiển; chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường đối với xe cơ giới theo quy định của pháp luật; chứng nhận bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=138;
