INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khu vực có trường học, bệnh viện, bến xe, công trình công cộng tập trung đông người, khu vực đông dân cư, chợ, khu vực đang thi công trên đường bộ, hiện trường vụ tai nạn giao thông đường bộ.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=165;
