INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đón, trả hành khách đúng nơi quy định; hướng dẫn sử dụng trang thiết bị an toàn trên xe; có biện pháp giữ gìn vệ sinh trong xe; vận chuyển hành khách đúng lịch trình, lộ trình đã đăng ký, trừ trường hợp bất khả kháng; không chở hành khách trên nóc xe, trong khoang chở hành lý hoặc để hành khách đu, bám bên ngoài xe.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=168;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đón, trả hành khách theo yêu cầu của hành khách trên xe; hướng dẫn sử dụng trang thiết bị an toàn trên xe; có biện pháp giữ gìn vệ sinh trong xe; vận chuyển hành khách đúng lịch trình, lộ trình đã đăng ký, trừ trường hợp bất khả kháng; không chở hành khách trên nóc xe, trong khoang chở hành lý hoặc để hành khách đu, bám bên ngoài xe.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=168;
