INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải có giấy phép vận chuyển; trong trường hợp cần thiết, đơn vị vận chuyển hàng hoá nguy hiểm phải bố trí người áp tải để bảo đảm trật tự, an toàn giao thông đường bộ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=176;
