INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),177,'Việc lưu hành xe ô tô của người nước ngoài đăng ký tại nước ngoài có tay lái ở bên phải tham gia giao thông tại Việt Nam, xe cơ giới nước ngoài do người nước ngoài đưa vào Việt Nam du lịch được quy định như như thế nào?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',41);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải chấp hành quy định của pháp luật về trật tự, an toàn giao thông đường bộ của Việt Nam. Trường hợp điều ước quốc tế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên có quy định khác thì áp dụng theo điều ước quốc tế đó.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=177;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tham gia giao thông đúng trong phạm vi, tuyến đường, thời gian đã được cơ quan có thẩm quyền của Việt Nam cấp phép.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=177;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe ô tô của người nước ngoài đăng ký tại nước ngoài có tay lái ở bên phải phải đi theo đoàn và có người, phương tiện hỗ trợ, hướng dẫn giao thông.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=177;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',1,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=177;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),178,'Việc sử dụng xe mô tô, xe gắn máy, xe thô sơ để vận chuyển hành khách, hàng hóa phải thực hiện các quy định nào dưới đây để đảm bảo an toàn giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',41);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Kiểm tra điều kiện bảo đảm an toàn của xe trước khi tham gia giao thông đường bộ; mang đủ giấy tờ theo quy định của pháp luật.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=178;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Kiểm tra việc sắp xếp hàng hóa bảo đảm an toàn; không chở quá số người, chở hành lý, hàng hoá vượt quá khối lượng cho phép hoặc vượt quá khổ giới hạn của xe.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=178;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=178;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),179,'Xe vận chuyển hàng siêu trường, siêu trọng phải thực hiện các quy định nào dưới đây để bảo đảm an toàn giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',41);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải chạy với tốc độ quy định trong giấy phép và phải có báo hiệu kích thước của hàng; trường hợp cần thiết, phải có người, phương tiện hỗ trợ lái xe, cảnh báo cho người, phương tiện tham gia giao thông đường bộ khác và thực hiện các biện pháp bảo đảm an toàn giao thông khi vận chuyển hàng siêu trường, siêu trọng trên đường bộ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=179;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải chạy với tốc độ quy định trong giấy phép; phải có người, phương tiện hỗ trợ lái xe, cảnh báo cho người, phương tiện tham gia giao thông đường bộ khác và thực hiện các biện pháp bảo đảm an toàn giao thông khi vận chuyển hàng siêu trường, siêu trọng trên đường dành cho giao thông công cộng.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=179;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH1'),180,'Xe cứu hộ giao thông đường bộ cần thực hiện yêu cầu nào sau đây để bảo đảm trật tự an toàn giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',42);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Xe cứu hộ giao thông đường bộ phải có dấu hiệu nhận diện, niêm yết thông tin trên xe, gắn thiết bị giám sát hành trình và thiết bị ghi nhận hình ảnh người lái xe.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=180;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải tuân thủ quy định của pháp luật về khối lượng hàng hóa chuyên chở của xe cứu hộ và khối lượng của xe được cứu hộ ghi trên Chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=180;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên. NĂNG PHÒNG CHÁY, CHỮA CHÁY VÀ CỨU HỘ, CỨU NẠN',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=180;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),181,'Người lái xe kinh doanh vận tải khi thực hiện tốt việc rèn luyện, nâng cao trách nhiệm, đạo đức nghề nghiệp sẽ thu được kết quả như thế nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',43);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Được khách hàng, xã hội tôn trọng; được đồng nghiệp quý mến, giúp đỡ; được doanh nghiệp tin dùng và đóng góp nhiều cho xã hội; thu hút được khách hàng, góp phần quan trọng trong xây dựng thương hiệu, kinh doanh có hiệu quả cao.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=181;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Được cộng điểm vào giấy phép lái xe.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=181;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=181;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),182,'Những hành vi nào sau đây thể hiện là người có văn hóa giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',43);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Luôn tuân thủ pháp luật về trật tự, an toàn giao thông đường bộ, nhường nhịn và giúp đỡ người khác.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=182;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đi nhanh, vượt đèn đỏ nếu không có lực lượng Công an.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=182;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Bấm còi và nháy đèn liên tục để cảnh báo xe khác.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=182;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tránh nhường đường để đi nhanh hơn.',0,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=182;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),183,'Người lái xe kinh doanh vận tải cần thực hiện những công việc gì ghi ở dưới đây để thường xuyên rèn luyện nâng cao đạo đức nghề nghiệp?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',43);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quản lý và sử dụng xe tốt; bảo dưỡng xe đúng định kỳ; thực hành tiết kiệm vật tư, nhiên liệu; luôn tu dưỡng bản thân, có lối sống lành mạnh, tác phong làm việc công nghiệp.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=183;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nắm vững và tự giác chấp hành các quy định của pháp luật về trật tự, an toàn giao thông đường bộ, lái xe an toàn; thực hiện đầy đủ trách nhiệm với khách hàng; có ý thức tổ chức kỷ luật và xây dựng doanh nghiệp vững mạnh; có tinh thần hợp tác, tương trợ, giúp đỡ đồng nghiệp.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=183;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=183;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),184,'Người lái xe ô tô vận chuyển hành khách phải có những phẩm chất, đạo đức nghề nghiệp gì dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',43);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Phải có thái độ lịch sự, tôn trọng, thân mật với hành khách; giúp đỡ những người có hoàn cảnh khó khăn, người già, người khuyết tật, phụ nữ có thai, có con nhỏ và trẻ em.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=184;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Luôn tu dưỡng bản thân, có lối sống lành mạnh, khiêm tốn, có tác phong làm việc công nghiệp, không tham gia vào các tệ nạn xã hội; tôn trọng người cùng tham gia giao thông đường bộ và có ý thức bảo vệ môi trường.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=184;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=184;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),185,'Khái niệm về văn hóa giao thông được hiểu như thế nào là đúng?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',43);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là sự hiểu biết và chấp hành nghiêm chỉnh pháp luật về giao thông, là ý thức trách nhiệm với cộng đồng khi tham gia giao thông.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=185;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Là sự tôn trọng, nhường nhịn, giúp đỡ và ứng xử có văn hóa giữa những người tham gia giao thông với nhau.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=185;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=185;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),186,'Trên làn đường dành cho ô tô có vũng nước lớn, người lái xe ô tô bắt buộc phải đi qua vũng nước, trên làn đường bên cạnh có nhiều người đang lái xe mô tô tham gia giao thông, người lái xe ô tô xử lý như thế nào khi lái xe qua vũng nước là có văn hóa giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',44);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cho xe chạy thật nhanh qua vũng nước.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=186;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giảm tốc độ cho xe chạy chậm qua vũng nước.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=186;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giảm tốc độ cho xe chạy qua làn đường dành cho mô tô để tránh vũng nước.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=186;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),187,'Người lái xe không điều khiển xe đi đúng làn đường quy định, phóng nhanh, vượt ẩu, vượt đèn đỏ, đi vào đường cấm được coi là hành vi nào trong các hành vi dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',44);
