INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Hiểu biết và chấp hành nghiêm chỉnh pháp luật về giao thông đường bộ; có ý thức trách nhiệm với cộng đồng khi tham gia giao thông; tôn trọng, nhường nhịn, giúp đỡ và ứng xử có văn hóa với những người cùng tham gia giao thông.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=189;
