INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Điều khiển xe đi trên phần đường, làn đường có ít phương tiện tham gia giao thông, chỉ đội mũ bảo hiểm ở nơi có biển báo bắt buộc đội mũ bảo hiểm.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=190;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chấp hành hiệu lệnh, chỉ dẫn của người điều khiển giao thông, quy định về tốc độ, tín hiệu đèn, biển báo hiệu, vạch kẻ đường khi lái xe; nhường đường cho người đi bộ, người già, trẻ em, người khuyết tật.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=190;
