INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dừng ngay phương tiện, cảnh báo nguy hiểm, giữ nguyên hiện trường, trợ giúp người bị nạn và báo tin cho cơ quan Công an, cơ sở khám bệnh, chữa bệnh.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=194;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Ở lại hiện trường vụ tai nạn giao thông đường bộ cho đến khi người của cơ quan Công an đến, trừ trường hợp phải đi cấp cứu, đưa người bị nạn đi cấp cứu hoặc xét thấy bị đe dọa đến tính mạng, sức khỏe nhưng phải đến trình báo ngay cơ quan Công an, Ủy ban nhân dân nơi gần nhất.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=194;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cung cấp thông tin xác định danh tính về bản thân, người liên quan đến vụ tai nạn giao thông đường bộ và thông tin liên quan của vụ tai nạn giao thông đường bộ cho cơ quan có thẩm quyền.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=194;
