INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chỉ quan sát rồi tiếp tục di chuyển.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=199;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Chỉ giúp đỡ nếu có người thân trong vụ tai nạn.',0,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=199;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),200,'Trong đoạn đường hai chiều tại khu đông dân cư đang ùn tắc, người điều khiển xe mô tô có văn hóa giao thông sẽ lựa chọn cách xử lý tình huống nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',46);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cho xe lấn sang làn ngược chiều để nhanh chóng thoát khỏi nơi ùn tắc.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=200;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Điều khiển xe trên vỉa hè để nhanh chóng thoát khỏi nơi ùn tắc.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=200;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Kiên nhẫn tuân thủ hướng dẫn của người điều khiển giao thông hoặc tín hiệu đèn giao thông, di chuyển trên đúng phần đường bên phải theo chiều đi, nhường đường cho các phương tiện đi ngược chiều.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=200;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),201,'Khi điều khiển phương tiện tham gia giao thông trên đoạn đường bộ đang xảy ra ùn tắc, những hành vi nào dưới đây là thiếu văn hóa?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',47);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Bấm còi liên tục thúc giục các phương tiện phía trước nhường đường; đi trên vỉa hè, tận dụng mọi khoảng trống để nhanh chóng thoát khỏi nơi ùn tắc; lấn sang trái đường cố gắng vượt lên xe khác.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=201;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tuân thủ hướng dẫn của người điều khiển giao thông hoặc tín hiệu giao thông, đi đúng phần đường, làn đường quy định.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=201;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),202,'Người lái xe, chủ phương tiện giao thông cơ giới đường bộ nên thực hiện các biện pháp phòng cháy, chữa cháy như thế nào dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',47);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Không lắp đặt thêm thiết bị điện, phụ kiện không đúng theo thiết kế của nhà sản xuất; tuân thủ quy trình vận hành bảo trì bảo dưỡng định kỳ; thường xuyên kiểm tra phương tiện, khi phát hiện thấy dấu hiệu khác lạ (khó nổ, có hơi xăng, có tiếng kêu bất thường, nhiệt độ của máy cao, có mùi khét) cần khắc phục ngay.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=202;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi để xe trong nhà, ở nơi trông giữ xe phải tắt khóa điện, để xa nguồn lửa, nguồn nhiệt; không mua xăng, dầu ở các điểm bán tự phát, không rõ nguồn gốc; không sử dụng các biện pháp “tiết kiệm xăng, dầu” khi chưa được kiểm chứng về mức độ an toàn có thể gây hỏng xe hoặc dẫn đến nguy cơ xảy ra cháy cao.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=202;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Không để các chất dễ cháy, dễ bắt lửa trong xe, dưới yên xe, trong cốp xe, trong khoang động cơ. Đối với xe điện cần chọn địa điểm sạc an toàn, sử dụng các thiết bị sạc đúng cách và giám sát quá trình sạc.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=202;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',1,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=202;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),203,'Người điều khiển phương tiện cơ giới đường bộ phải thực hiện những biện pháp gì dưới đây để chữa cháy trong trường hợp phương tiện bị cháy, xét thấy có khả năng dập tắt đám cháy?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',47);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tắt khoá điện, hô hoán để mọi người đến trợ giúp chữa cháy, gọi Cảnh sát phòng cháy chữa cháy và cứu nạn cứu hộ (điện thoại 114).',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=203;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nếu nhiên liệu chưa trào ra ngoài (ngọn lửa chưa cháy dữ dội) thì có thể sử dụng nước, hoặc bất kỳ chất, phương tiện chữa cháy có được để dập lửa; nếu nhiên liệu đã trào ra ngoài (ngọn lửa cháy dữ dội) thì phải sử dụng các bình chữa cháy, cát, chăn chiên, bao tải, vải nhúng nước để dập lửa.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=203;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả hai ý trên.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=203;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),204,'Khi phát hiện thấy có ngọn lửa, khói hoặc nhiệt độ cao bất thường từ phương tiện giao thông do mình điều khiển người lái xe phải làm gì trước tiên?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',47);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Bình tĩnh, đưa xe sát vào lề đường, tránh xa nơi có nhiều người, nhiều chất dễ cháy và tắt khóa điện, thực hiện các bước chữa cháy.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=204;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Hô hoán để mọi người đến trợ giúp chữa cháy, gọi Cảnh sát giao thông, Cảnh sát phòng cháy, chữa cháy và cứu nạn, cứu hộ, lực lượng y tế để sẵn sàng hỗ trợ cứu người.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=204;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nếu nhiên liệu trào ra ngoài, ngọn lửa chưa cháy dữ dội thì tiếp tục sử dụng nước, hoặc bất kỳ chất, phương tiện chữa cháy có được để dập lửa.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=204;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',0,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=204;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH2'),205,'Khi gặp nạn nhân bị bỏng trong vụ tai nạn giao thông, người lái xe cần làm gì?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',48);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Gọi số 115 để thông báo về tình trạng tai nạn và yêu cầu hỗ trợ y tế ngay lập tức. Quan sát hiện trường để giúp nạn nhân, đồng thời tránh gây tổn thương cho mình.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=205;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nhanh chóng loại bỏ nguyên nhân gây bỏng bằng cách tách nạn nhân khỏi vật gây cháy, cởi bỏ quần áo nếu bén lửa, ngâm vùng da bị bỏng vào nước sạch hoặc đắp khăn mát, lưu ý không dùng khăn hoặc nước quá lạnh.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=205;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nếu nạn nhân còn tỉnh, cần cho uống bù nước. Trong thời tiết lạnh, cần giữ ấm cho cơ thể nạn nhân, sau đó nhanh chóng đưa đến cơ sở y tế gần nhất.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=205;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cả ba ý trên.',1,4 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=205;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),206,'Khi điều khiển xe mô tô tay ga xuống đường dốc dài, độ dốc cao, người lái xe cần thực hiện các thao tác nào dưới đây để bảo đảm an toàn?',NULL,NULL,1,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',49);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giữ tay ga ở mức độ phù hợp, sử dụng phanh trước và phanh sau để giảm tốc độ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=206;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Nhả hết tay ga, tắt động cơ, sử dụng phanh trước và phanh sau để giảm tốc độ.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=206;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Sử dụng phanh trước để giảm tốc độ kết hợp với tắt chìa khóa điện của xe.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=206;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),207,'Khi vào số để khởi hành xe ô tô có số tự động, người lái xe phải thực hiện các thao tác nào để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',49);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đạp bàn đạp phanh chân hết hành trình, vào số và nhả phanh đỗ, kiểm tra lại xem có bị nhầm số không rồi mới cho xe lăn bánh.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=207;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Đạp bàn đạp để tăng ga với mức độ phù hợp, vào số và kiểm tra lại xem có bị nhầm số không rồi mới cho xe lăn bánh.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=207;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),208,'Khi nhả phanh đỗ cơ khí điều khiển bằng tay (phanh tay), người lái xe cần phải thực hiện các thao tác nào?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',49);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dùng lực tay phải kéo cần phanh tay về phía sau hết hành trình; nếu khóa hãm bị kẹt cứng phải đẩy mạnh phanh tay về phía trước, sau đó bóp khóa hãm.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=208;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dùng lực tay phải bóp khóa hãm đẩy cần phanh tay về phía trước hết hành trình; nếu khóa hãm bị kẹt cứng phải kéo cần phanh tay về phía sau đồng thời bóp khóa hãm.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=208;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Dùng lực tay phải đẩy cần phanh tay về phía trước hết hành trình; nếu khóa hãm bị kẹt cứng phải đẩy mạnh phanh tay về phía trước, sau đó bóp khóa hãm.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=208;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),209,'Khi khởi hành ô tô sử dụng hộp số cơ khí trên đường bằng, người lái xe cần thực hiện các thao tác nào theo trình tự dưới đây?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',49);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Kiểm tra an toàn xung quanh xe ô tô; nhả từ từ đến 1/2 hành trình bàn đạp ly hợp (côn) và giữ trong khoảng 3 giây; vào số 1; nhả hết phanh tay, báo hiệu bằng còi, đèn trước khi xuất phát; tăng ga đủ để xuất phát, sau đó vừa tăng ga vừa nhả hết côn để cho xe ô tô chuyển động.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=209;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Kiểm tra an toàn xung quanh xe ô tô; đạp ly hợp (côn) hết hành trình; vào số 1; nhả hết phanh tay, báo hiệu bằng còi, đèn trước khi xuất phát; tăng ga đủ để xuất phát; nhả từ từ đến 1/2 hành trình bàn đạp côn và giữ trong khoảng 3 giây, sau đó vừa tăng ga vừa nhả hết côn để cho xe ô tô chuyển động.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=209;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),210,'Khi quay đầu xe, người lái xe cần phải quan sát và thực hiện các thao tác nào để bảo đảm an toàn giao thông?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',49);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát biển báo hiệu để biết nơi được phép quay đầu; quan sát kỹ địa hình nơi chọn để quay đầu; lựa chọn quỹ đạo quay đầu xe cho thích hợp; quay đầu xe với tốc độ thấp; thường xuyên báo tín hiệu để người, các phương tiện xung quanh được biết; nếu quay đầu xe ở nơi nguy hiểm thì đưa đầu xe về phía nguy hiểm, đưa đuôi xe về phía an toàn.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=210;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát biển báo hiệu để biết nơi được phép quay đầu; quan sát kỹ địa hình nơi chọn để quay đầu; lựa chọn quỹ đạo quay đầu xe; quay đầu xe với tốc độ tối đa; thường xuyên báo tín hiệu để người, các phương tiện xung quanh được biết; nếu quay đầu xe ở nơi nguy hiểm thì đưa đuôi xe về phía nguy hiểm và đầu xe về phía an toàn.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=210;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),211,'Khi ngồi lái ô tô tư thế chân, lưng, tay của người lái xe như thế nào là đúng để bảo đảm an toàn và thoải mái?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',50);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Điều chỉnh ghế sao cho chân có thể đạp phanh và ga dễ dàng, ngồi thẳng lưng, hai tay nắm vô lăng, tay trái nắm ở vị trí 9 đến 10 giờ và tay phải nắm ở vị trí từ 2 đến 4 giờ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=211;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Ngồi sát vô lăng để dễ quan sát hoặc ngồi tự do, không cần điều chỉnh ghế.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=211;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Ngồi ngả người về phía sau nhiều để thư giãn, chân trái để ở vị trí chân ga, hai tay nắm vô lăng ở vị trí bất kỳ.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=211;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),212,'Khi điều khiển ô tô lên dốc cao, người lái xe cần thực hiện các thao tác nào dưới đây để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',50);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng lên số cao từ chân dốc, điều chỉnh ga cho xe nhanh lên dốc; đến gần đỉnh dốc phải tăng ga để xe nhanh chóng qua dốc; về số thấp, đi sát về phía bên phải đường, có tín hiệu (còi, đèn) để báo cho người lái xe đi ngược chiều biết.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=212;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Về số thấp từ chân dốc, điều chỉnh ga cho xe từ từ lên dốc; đến gần đỉnh dốc phải đi chậm, đi sát về phía bên phải đường, có tín hiệu (còi, đèn) để báo cho người lái xe đi ngược chiều biết.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=212;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),213,'Khi điều khiển ô tô xuống dốc dài, người lái xe cần thực hiện các thao tác nào dưới đây để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',50);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng lên số cao, nhả bàn đạp ga ở mức độ phù hợp, kết hợp với phanh chân để khống chế tốc độ.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=213;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Về số thấp, nhả bàn đạp ga ở mức độ phù hợp, kết hợp với phanh chân để khống chế tốc độ.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=213;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Về số không (0), nhả bàn đạp ga ở mức độ phù hợp, kết hợp với phanh chân để khống chế tốc độ.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=213;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),214,'Khi xuống dốc, muốn dừng xe, người lái xe cần thực hiện các thao tác nào để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',50);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có tín hiệu rẽ phải, điều khiển xe sát vào lề đường bên phải; đạp phanh sớm và mạnh hơn lúc dừng xe trên đường bằng để xe đi với tốc độ chậm đến mức dễ dàng dừng lại được; về số 1, đạp 1/2 ly hợp (côn) cho xe đến chỗ dừng; khi xe đã dừng, về số không (N), đạp phanh chân, sử dụng phanh đỗ.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=214;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có tín hiệu rẽ phải, điều khiển xe sát vào lề đường bên trái; đạp hết hành trình ly hợp (côn) và nhả bàn đạp ga để xe đi với tốc độ chậm đến mức dễ dàng dừng lại được tại chỗ dừng; khi xe đã dừng, đạp và giữ phanh chân.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=214;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có tín hiệu rẽ trái, điều khiển xe sát vào lề đường bên phải; đạp phanh sớm và mạnh hơn lúc dừng xe trên đường bằng để xe đi với tốc độ chậm đến mức dễ dàng dừng lại được; về số không (N) để xe đi đến chỗ dừng, khi xe đã dừng, sử dụng phanh đỗ.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=214;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),215,'Khi điều khiển xe trên đường vòng người lái xe cần phải làm gì để bảo đảm an toàn?',NULL,NULL,1,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,B1,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',51);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát cẩn thận các chướng ngại vật và báo hiệu bằng coi, đèn; giảm tốc độ tới mức cần thiết, về số thấp và thực hiện quay vòng với tốc độ phù hợp với bán kính cong của đường vòng.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=215;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát cẩn thận các chướng ngại vật và báo hiệu bằng còi, đèn; tăng tốc để nhanh chóng qua đường vòng và giảm tốc độ sau khi qua đường vòng.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=215;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),216,'Khi điều khiển xe ô tô rẽ phải, người lái xe cần thực hiện các thao tác nào để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',51);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Có tín hiệu rẽ phải; quan sát an toàn phía sau; điều khiển xe sang làn đường bên trái; giảm tốc độ và quan sát an toàn phía bên phải để điều khiển xe qua chỗ đường giao nhau.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=216;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ phải; giảm tốc độ, quan sát an toàn phía trước, sau, bên phải và điều khiển xe từ từ rẽ phải.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=216;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ phải; quan sát an toàn phía sau; điều khiển xe bám sát vào phía phải đường; tăng tốc độ và quan sát an toàn phía bên trái để điều khiển xe qua chỗ đường giao nhau.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=216;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),217,'Khi điều khiển xe ô tô rẽ trái, người lái xe cần thực hiện các thao tác nào để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',51);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ trái; giảm tốc độ, quan sát an toàn xung quanh đặc biệt là bên trái; đổi sang làn đường bên trái và điều khiển xe từ từ rẽ trái.',1,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=217;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ trái, tăng tốc độ để xe nhanh chóng qua chỗ đường giao nhau; có tín hiệu xin đổi làn đường; quan sát an toàn xung quanh đặc biệt là bên trái; đổi làn đường sang phải để mở rộng vòng cua.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=217;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),218,'Khi điều khiển xe sử dụng hộp số cơ khí vượt qua rãnh lớn cắt ngang mặt đường, người lái xe cần thực hiện các thao tác nào để đảm bảo an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',51);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Vào số một (1) và từ từ cho hai bánh xe trước xuống rãnh, tăng ga cho hai bánh xe trước vượt lên khỏi rãnh, tăng số, tăng tốc độ để bánh xe sau vượt qua rãnh.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=218;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Tăng ga, tăng số để hai bánh xe trước và bánh xe sau vượt qua khỏi rãnh và chạy bình thường.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=218;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Vào số một (1) và từ từ cho hai bánh xe trước xuống rãnh, tăng ga cho hai bánh xe trước vượt lên khỏi rãnh, tiếp tục để bánh xe sau từ từ xuống rãnh rồi tăng dần ga cho xe ô tô lên khỏi rãnh.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=218;
INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),219,'Khi điều khiển xe qua đường sắt, người lái xe cần phải thực hiện các thao tác nào dưới đây để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,A1,A,B1,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',52);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi có chuông báo hoặc thanh chắn đã hạ xuống, người lái xe phải dừng xe tạm thời đúng khoảng cách an toàn, kéo phanh tay nếu đường dốc hoặc phải chờ lâu.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=219;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi không có chuông báo hoặc thanh chắn không hạ xuống, người lái xe cần phải quan sát nếu thấy đủ điều kiện an toàn thì về số thấp, tăng ga nhẹ và không thay đổi số trong quá trình vượt qua đường sắt để tránh động cơ chết máy cho xe cho vượt qua.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=219;
