INSERT INTO theory_questions (category_code,topic_id,question_number,content,image_url,explanation,is_paralysis,version,verification_status,legal_reference,is_active,applicable_categories,paralysis_categories,source_hash,source_page) VALUES ('ALL',(SELECT id FROM theory_topics WHERE code='PDF25_CH3'),220,'Khi điều khiển xe ô tô tự đổ, người lái xe cần chú ý những điểm gì để bảo đảm an toàn?',NULL,NULL,0,'PDF-2025-6a6dab85','VERIFIED','PDF người dùng; CV 2262/CSGT-P5 (07/05/2025), PL1–3',1,',B,C1,C,D1,D2,D,BE,C1E,CE,D1E,D2E,DE,',',,','6a6dab8543eb334b36ac9de6abcd938e864f2e0e915be27c3a2157ee6e518575',52);
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi chạy trên đường xấu, nhiều ổ gà nên chạy chậm để thùng xe không bị lắc mạnh, không gây hiện tượng lệch "ben"; khi chạy vào đường vòng, cần giảm tốc độ, không lấy lái gấp và không phanh gấp.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=220;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi chạy trên đường quốc lộ, đường bằng phẳng không cần hạ hết thùng xe xuống.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=220;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi đổ hàng phải chọn vị trí có nền đường cứng và phẳng, dừng hẳn xe, kéo hết phanh đỗ; sau đó mới điều khiển cơ cấu nâng "ben" để đổ hàng, đổ xong hàng mới hạ thùng xuống.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=220;
