INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Về số thấp phù hợp, nhả bàn đạp ga, kết hợp đạp phanh chân với mức độ phù hợp để giảm tốc độ.',1,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=223;
