INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát, ước lượng độ ngập nước mà xe ô tô có thể vượt qua an toàn, về số thấp, giữ đều ga và giữ vững tay lái để ô tô vượt qua đoạn đường ngập nước.',1,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=224;
