INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giảm tốc độ đến mức an toàn, quan sát, nhường đường cho người đi bộ, giữ khoảng cách an toàn với các xe phía trước.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=247;
