INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Giữ khoảng cách an toàn, tránh đi vào vị trí điểm mù của xe kéo rơ moóc, bật xi nhan trái đồng thời kết hợp đèn, còi xin vượt.',0,1 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=251;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi xe kéo rơ moóc đã có tín hiệu cho vượt (không có chướng ngại vật phía trước và xe đi ngược chiều), thấy đủ điều kiện an toàn thì vượt dứt khoát, không di chuyển song song bên cạnh xe kéo rơ moóc.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=251;
INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi vượt qua, phải quan sát gương chiếu hậu bên phải nếu có khoảng trống an toàn mới được cho xe chạy vào làn của mình, tắt xi nhan và tiếp tục hành trình.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=251;
