INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Quan sát xe đang đi trên đường chính, nếu là xe có kích thước lớn hơn thì nhường đường, xe có kích thước nhỏ hơn thì tăng tốc độ cho xe đi ra đường chính.',0,3 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=253;
