INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Lốp phải đủ số lượng, đủ áp suất, không phồng rộp, đúng cỡ lốp của nhà sản xuất hoặc tài liệu kỹ thuật quy định; lốp trên cùng một trục của xe sử dụng trong điều kiện hoạt động bình thường phải cùng kiểu loại.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=269;
