INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Khi hoạt động các cơ cấu chuyển động của hệ thống lái không được va chạm với bất kỳ bộ phận nào của xe; khi quay vô lăng lái về bên phải và bên trái thì không được có sự khác biệt đáng kể về lực tác động lên vành tay lái.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=270;
