INSERT INTO theory_answers (question_id,answer_text,is_correct,order_index) SELECT id,'Ngăn ngừa và phát hiện kịp thời các hư hỏng và sai lệch kỹ thuật để khắc phục, giữ gìn được hình thức bên ngoài.',0,2 FROM theory_questions WHERE version='PDF-2025-6a6dab85' AND question_number=271;
